#include "linux_wayland.h"
#include "window/window_inc.h"

#include <string.h>
#include <wayland-client.h>

// Generated by wayland-scanner in build.sh
#include "generated/xdg-shell-client-protocol.h"
#include "generated/xdg-shell-protocol.c"

#define WL_COMPOSITOR_MAX_VERSION 4
#define XDG_WM_BASE_VERSION 1

static void registry_global(void *data, struct wl_registry *registry, u32 name,
                            const char *interface, u32 version)
{
    linux_wayland_window_t *window = data;

    if (0 == strcmp(interface, wl_compositor_interface.name)) {
        u32 v = MIN(version, WL_COMPOSITOR_MAX_VERSION);
        window->compositor = wl_registry_bind(registry, name, &wl_compositor_interface, v);
    } else if (0 == strcmp(interface, xdg_wm_base_interface.name)) {
        window->wm_base =
            wl_registry_bind(registry, name, &xdg_wm_base_interface, XDG_WM_BASE_VERSION);
    }
}

static void registry_global_remove(void *data, struct wl_registry *registry, u32 name)
{
    (void)data;
    (void)registry;
    (void)name;
}

static const struct wl_registry_listener registry_listener = {
    .global = registry_global,
    .global_remove = registry_global_remove,
};

static void wm_base_ping(void *data, struct xdg_wm_base *wm_base, u32 serial)
{
    (void)data;
    xdg_wm_base_pong(wm_base, serial);
}

static const struct xdg_wm_base_listener wm_base_listener = {
    .ping = wm_base_ping,
};

static void xdg_surface_configure(void *data, struct xdg_surface *xdg_surface, u32 serial)
{
    linux_wayland_window_t *window = data;
    xdg_surface_ack_configure(xdg_surface, serial);
    window->configured = true;
}

static const struct xdg_surface_listener xdg_surface_listener = {
    .configure = xdg_surface_configure,
};

static void xdg_toplevel_configure(void *data, struct xdg_toplevel *toplevel, i32 width,
                                   i32 height, struct wl_array *states)
{
    (void)toplevel;
    (void)states;
    linux_wayland_window_t *window = data;

    if (width > 0 && height > 0) {
        window->base.width = width;
        window->base.height = height;
    }
}

static void xdg_toplevel_close(void *data, struct xdg_toplevel *toplevel)
{
    (void)toplevel;
    linux_wayland_window_t *window = data;
    window->base.should_close = true;
}

static const struct xdg_toplevel_listener xdg_toplevel_listener = {
    .configure = xdg_toplevel_configure,
    .close = xdg_toplevel_close,
};

void window_destroy(window_t *base)
{
    if (NULL == base) {
        return;
    }
    linux_wayland_window_t *window = CONTAINER_OF(base, linux_wayland_window_t, base);

    if (window->xdg_toplevel)
        xdg_toplevel_destroy(window->xdg_toplevel);
    if (window->xdg_surface)
        xdg_surface_destroy(window->xdg_surface);
    if (window->surface)
        wl_surface_destroy(window->surface);
    if (window->wm_base)
        xdg_wm_base_destroy(window->wm_base);
    if (window->compositor)
        wl_compositor_destroy(window->compositor);
    if (window->registry)
        wl_registry_destroy(window->registry);
    if (window->display)
        wl_display_disconnect(window->display);

    *window = (linux_wayland_window_t){};
}

window_t *window_create(arena_t *arena, window_params_t params)
{
    linux_wayland_window_t *window = PUSH_STRUCT(arena, linux_wayland_window_t);
    *window = (linux_wayland_window_t){
        .base = {
            .title = params.title,
            .width = params.width,
            .height = params.height,
        },
    };

    window->display = wl_display_connect(NULL);
    if (NULL == window->display) {
        printf("cannot connect to the wayland display");
        goto fail;
    }

    window->registry = wl_display_get_registry(window->display);
    wl_registry_add_listener(window->registry, &registry_listener, window);

    wl_display_roundtrip(window->display);

    if (NULL == window->compositor || NULL == window->wm_base) {
        printf("compositor lacks wl_compositor or xdg_wm_base");
        goto fail;
    }
    xdg_wm_base_add_listener(window->wm_base, &wm_base_listener, window);

    window->surface = wl_compositor_create_surface(window->compositor);
    window->xdg_surface = xdg_wm_base_get_xdg_surface(window->wm_base, window->surface);
    xdg_surface_add_listener(window->xdg_surface, &xdg_surface_listener, window);

    window->xdg_toplevel = xdg_surface_get_toplevel(window->xdg_surface);
    xdg_toplevel_add_listener(window->xdg_toplevel, &xdg_toplevel_listener, window);
    xdg_toplevel_set_title(window->xdg_toplevel, params.title);
    xdg_toplevel_set_app_id(window->xdg_toplevel, params.title);

    wl_surface_commit(window->surface);
    while (!window->configured) {
        if (-1 == wl_display_dispatch(window->display)) {
            printf("lost connection waiting for first configure");
            goto fail;
        }
    }

    return &window->base;

fail:
    window_destroy(&window->base);
    return NULL;
}
